class _CalcError(Exception):
    pass


def calc(expr: str) -> int | str:
    s = expr.replace(" ", "")
    n = len(s)
    pos = 0

    def parse_expr() -> int:
        val = parse_term()
        while pos < n and s[pos] in "+-":
            op = s[pos]
            pos_inc()
            rhs = parse_term()
            if op == "+":
                val += rhs
            else:
                val -= rhs
        return val

    def pos_inc() -> None:
        nonlocal pos
        pos += 1

    def parse_term() -> int:
        val = parse_unary()
        while pos < n and s[pos] in "*/%":
            op = s[pos]
            pos_inc()
            rhs = parse_unary()
            if op == "*":
                val *= rhs
            else:
                if rhs == 0:
                    raise _CalcError()
                q = abs(val) // abs(rhs)
                if (val < 0) ^ (rhs < 0):
                    q = -q
                if op == "/":
                    val = q
                else:
                    val = val - rhs * q
        return val

    def parse_unary() -> int:
        neg = False
        while pos < n and s[pos] == "-":
            pos_inc()
            neg = not neg
        val = parse_pow()
        return -val if neg else val

    def parse_pow() -> int:
        bases = [parse_atom()]
        negs = []
        while pos < n and s[pos] == "^":
            pos_inc()
            neg = False
            while pos < n and s[pos] == "-":
                pos_inc()
                neg = not neg
            negs.append(neg)
            bases.append(parse_atom())
        val = bases[-1]
        for i in range(len(negs) - 1, -1, -1):
            if negs[i]:
                val = -val
            if val < 0:
                raise _CalcError()
            val = bases[i] ** val
        return val

    def parse_atom() -> int:
        nonlocal pos
        if s[pos] == "(":
            pos += 1
            val = parse_expr()
            pos += 1  # skip ')'
            return val
        start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        return int(s[start:pos])

    try:
        return parse_expr()
    except _CalcError:
        return "error"
